func warningSettingsLabel(s apiclient.WarningSettings) string {
	if !s.Runway && !s.Spent && !s.Unusual && !s.Burst {
		return "Off"
	}
	return "On"
}

func activeBudgetNotice(st *apiclient.MandateStatement) string {
	if st == nil {
		return ""
	}
	for _, kind := range []string{"spent", "unusual", "burst", "runway"} {
		for _, w := range st.Warnings {
			if w.ResolvedAt != nil || w.Kind != kind {
				continue
			}
			switch kind {
			case "spent":
				return "This total is spent"
			case "unusual":
				return "Usage is above its usual rate"
			case "burst":
				return "This new Card is being used quickly"
			case "runway":
				return "This total is running low"
			}
		}
	}
	return ""
}

